import sys


def main():
    flags = []
    filepath = None
    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg.startswith("-") and not arg.startswith("--"):
            for ch in arg[1:]:
                if ch in ("l", "w", "c"):
                    flags.append(ch)
                else:
                    print(f"Unknown flag: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif filepath is None:
            filepath = arg
        else:
            print("Unexpected argument", file=sys.stderr)
            sys.exit(1)
        i += 1

    # Default to all three if no flags given
    if not flags:
        flags = ["l", "w", "c"]

    # Determine input source
    if filepath is None or filepath == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, "rb") as f:
            data = f.read()

    lines = data.count(b"\n")
    # A final line without trailing newline still counts
    if data and not data.endswith(b"\n"):
        lines += 1
    words = len(data.split())
    chars = len(data)

    results = {flag: {"l": lines, "w": words, "c": chars}[flag] for flag in flags}
    print(" ".join(str(results[flag]) for flag in flags))


if __name__ == "__main__":
    main()

